BEGIN;
CREATE TABLE IF NOT EXISTS gov_daos(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gov_memberships(dao_id UUID NOT NULL REFERENCES gov_daos(id),user_id INTEGER NOT NULL REFERENCES users(id),wallet_address TEXT,role TEXT NOT NULL CHECK(role IN('member','proposer','reviewer','executor','auditor','admin')),voting_power_source TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(dao_id,user_id));
CREATE TABLE IF NOT EXISTS gov_contracts(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),chain_id BIGINT NOT NULL,governor_address TEXT NOT NULL,code_hash CHAR(64) NOT NULL,deployment_block BIGINT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,UNIQUE(dao_id,chain_id,governor_address));
CREATE TABLE IF NOT EXISTS gov_contract_targets(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),chain_id BIGINT NOT NULL,address TEXT NOT NULL,code_hash CHAR(64) NOT NULL,label TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,UNIQUE(dao_id,chain_id,address));
CREATE TABLE IF NOT EXISTS gov_proposals(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),chain_id BIGINT NOT NULL,governor_address TEXT NOT NULL,snapshot_block BIGINT NOT NULL,proposal_hash CHAR(64) NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,actions JSONB NOT NULL,status TEXT NOT NULL DEFAULT'draft' CHECK(status IN('draft','simulated','reviewed','voting','succeeded','defeated','cancelled','execution_ready','executed','execution_failed')),idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(dao_id,idempotency_key),UNIQUE(dao_id,proposal_hash));
CREATE TABLE IF NOT EXISTS gov_chain_snapshots(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),chain_id BIGINT NOT NULL,block_number BIGINT NOT NULL,block_hash TEXT NOT NULL,parent_hash TEXT NOT NULL,confirmations INTEGER NOT NULL DEFAULT 0,canonical BOOLEAN NOT NULL DEFAULT false,captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(chain_id,block_number,block_hash));
CREATE TABLE IF NOT EXISTS gov_votes(id BIGSERIAL PRIMARY KEY,proposal_id BIGINT NOT NULL REFERENCES gov_proposals(id),voter_address TEXT NOT NULL,choice TEXT NOT NULL CHECK(choice IN('for','against','abstain')),voting_power_units NUMERIC(78,0) NOT NULL,delegation_path JSONB NOT NULL,source_block_hash TEXT NOT NULL,transaction_hash TEXT,UNIQUE(proposal_id,voter_address));
CREATE TABLE IF NOT EXISTS gov_simulations(id BIGSERIAL PRIMARY KEY,proposal_id BIGINT NOT NULL REFERENCES gov_proposals(id),block_hash TEXT NOT NULL,state_diff_hash CHAR(64) NOT NULL,success BOOLEAN NOT NULL,trace JSONB NOT NULL,simulator_version TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gov_signing_requests(id BIGSERIAL PRIMARY KEY,proposal_id BIGINT NOT NULL REFERENCES gov_proposals(id),requested_by INTEGER NOT NULL REFERENCES users(id),payload JSONB NOT NULL,expires_at TIMESTAMPTZ NOT NULL,signature TEXT,transaction_hash TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gov_provider_syncs(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),provider TEXT NOT NULL,chain_id BIGINT NOT NULL,cursor TEXT,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,failure_detail TEXT,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,UNIQUE(dao_id,provider,chain_id,cursor));
CREATE TABLE IF NOT EXISTS gov_audit_events(id BIGSERIAL PRIMARY KEY,dao_id UUID NOT NULL REFERENCES gov_daos(id),proposal_id BIGINT REFERENCES gov_proposals(id),actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS gov_proposal_queue_idx ON gov_proposals(dao_id,status,updated_at);
COMMIT;
